Rules.InvariantScript:
If(
    var_tituloModulo = "Acesso indevido de fauna",
    Navigate(
        ScreenFauna,
        ScreenTransition.Fade
    ),
    Navigate(
        LookUp(
            col_NavTelas,
            Id = LookUp(
                col_menuModulos,
                Titulo = var_tituloModulo
            ).ID,
            TelaListar
        ),
        ScreenTransition.Fade
    )
);
Reset(RichTextDesdobramentosMsg)

