ControlPropertyState.AutoRuleBindingString:
If(
    RichTextDesdobramentosMsg.HtmlText = "",
    Notify(
        "Atenção o campo de texto deve ser preenchido!",
        NotificationType.Error
    ),
    Patch(
        tbl_desdobramentos,
        Defaults(tbl_desdobramentos),
        {
            Modulo: var_tituloModulo,
            ID_ocorrencia: var_desdobramentosSelect.ID,
            descricao: RichTextDesdobramentosMsg.HtmlText,
            Usuario: varNomeUser
        },
        FormDesdobramentosAnexo.Updates
    );
    ClearCollect(
        col_desdobramentos,
        Filter(
            tbl_desdobramentos,
            ID_ocorrencia = var_desdobramentosSelect.ID,
            Modulo = var_tituloModulo
        )
    );
    Notify(
        "Registro cadastrado com sucesso",
        NotificationType.Success
    );
    Reset(RichTextDesdobramentosMsg);
    ResetForm(FormDesdobramentosAnexo)
)

